#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);IDMA=${IDMA_ROOT:-$ROOT/work/upstream/idma};VD=$IDMA/target/sim/vcs;OUT=${OUT:-$ROOT/work/results/qwen2_kv_append_exact_backend};RUN=$ROOT/scripts/run_memory_capped.sh;mkdir -p "$OUT";[[ $(git -C "$IDMA" rev-parse HEAD) == 2e0b0fe53b6f8823319e2428e2e9abc2db149b7d ]];[[ -z $(git -C "$IDMA" status --porcelain) ]];"$ROOT/scripts/run_qwen2_q1024_exact_backend.sh";taskset -c 8-23 python3 "$ROOT/scripts/convert_qwen2_backend_kv_memh.py"|tee "$OUT/convert.log";taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_descriptor_macro_vectors.py" --packed-records "$ROOT/work/generated/qwen2_q1024_descriptor_image/packed_records.jsonl" --out "$OUT";taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_kv_append_context_vectors.py" --manifest "$ROOT/reports/execution/llama_cpp_qwen2_graph_lowering_manifest.jsonl" --out "$OUT"
AXI_INC=$(find "$IDMA/.bender/git/checkouts" -maxdepth 2 -path '*/axi-*/include'|head -n1);cd "$VD";run(){ local limit=$1;shift;MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s "$limit" taskset -c 8-23 "$@";};S=("$ROOT/rtl/integration/idma_backend_rw_axi_flat_wrap.sv" "$ROOT/rtl/kv/qwen2_kv_append_descriptor_v3_context.sv" "$ROOT/rtl/kv/qwen2_kv_append_ddr_page_core.sv" "$ROOT/rtl/kv/qwen2_kv_append_ddr_stage_top.sv" "$ROOT/tb/tb_qwen2_kv_append_repeated_payload_vcs.sv")
run 600s vlogan -sverilog -full64 +define+USE_UPSTREAM_IDMA +incdir+../../../src/include +incdir+"$AXI_INC" +incdir+"$ROOT" "${S[@]}" >"$OUT/vlogan.log" 2>&1;run 600s vcs -full64 -top tb_qwen2_kv_append_repeated_payload_vcs -o simv_kv_exact >"$OUT/vcs.log" 2>&1;cd "$ROOT";run 600s "$VD/simv_kv_exact" +MODEL_SOURCE=1 +COMMAND="$OUT/kv_append_command.memh" +RECORDS="$OUT/records.memh" +K="$ROOT/work/results/qwen2_q1024_exact_backend/k_rope.memh" +V="$ROOT/work/results/qwen2_q1024_exact_backend/v_bias.memh"|tee "$OUT/tb.log";! grep -q '^Error:' "$OUT/tb.log";grep -q 'QWEN2_KV_APPEND_PAYLOAD_PASS command=1 tokens=1024 pages=64.*source=exact_model_backend repeated_payload=0' "$OUT/tb.log"
